import {Component, OnInit} from '@angular/core';
import {Router, RouterModule, ActivatedRoute} from '@angular/router';
import {NgFor, NgIf, CommonModule} from '@angular/common';
import {ProductService} from '../product.service';
import {CartService} from '../services/cart.service';
import {Product} from '../models/product.model';

@Component({
    selector: 'app-view-all-products',
    standalone: true,
    imports: [RouterModule, NgFor, NgIf, CommonModule],
    templateUrl: './view-all-products.component.html',
    styleUrls: ['./view-all-products.component.css']
})
export class ViewAllProductsComponent implements OnInit {
    products: Product[] = [];
    filteredProducts: Product[] = [];
    loading: boolean = true;
    error: string | null = null;
    selectedBrand: string | null = null;
    sortOption: string = 'name'; // Changed default from 'popularity'
    currentPage: number = 0;
    pageSize: number = 20; // Default page size for loading products
    totalPages: number = 0;
    totalItems: number = 0;
    isFirstPage: boolean = true;
    isLastPage: boolean = false;
    searchTerm: string | null = null; // Added for search functionality

    // Paginated brand names for display
    paginatedBrands: string[] = [];
    brandPage: number = 0;
    brandPageSize: number = 10;
    totalBrandPages: number = 0;
    isFirstBrandPage: boolean = true;
    isLastBrandPage: boolean = false;

    constructor(
        private router: Router,
        private route: ActivatedRoute,
        private productService: ProductService,
        private cartService: CartService
    ) {}

    ngOnInit(): void {
        this.route.queryParams.subscribe(params => {
            this.currentPage = params['page'] ? +params['page'] : 0;
            this.selectedBrand = params['brand'] || null;
            this.sortOption = params['sort'] || 'name'; // Default sort to 'name' if not in params
            this.searchTerm = params['search'] || null; // Capture search term
            this.loadProducts(); // Load products based on URL params or defaults
        });
        // this.loadBrands(); // Brands can be loaded independently // Remove this line
        this.loadPaginatedBrands(); // Add this line
    }

    loadProducts(): void {
        this.loading = true;
        let sortByApi = 'name'; // Default sort field
        let sortDirApi = 'ASC'; // Default sort direction

        switch(this.sortOption) {
            case 'price-low-high':
                sortByApi = 'price'; // Assuming backend can sort by 'price'
                sortDirApi = 'ASC';
                break;
            case 'price-high-low':
                sortByApi = 'price'; // Assuming backend can sort by 'price'
                sortDirApi = 'DESC';
                break;
            case 'name':
                sortByApi = 'name';
                sortDirApi = 'ASC';
                break;
            default:
                // Handles 'popularity' or any other unknown option from UI
                if (this.sortOption === 'popularity') {
                    sortByApi = 'name'; // Fallback for 'popularity'
                    sortDirApi = 'ASC';
                    console.warn("Sorting by 'popularity' is not supported by the backend, defaulting to 'name'.");
                } else if (this.sortOption) {
                    // If sortOption is something else, try to use it, hoping it's valid
                    sortByApi = this.sortOption;
                    sortDirApi = 'ASC';
                } else {
                    // Fallback if sortOption is null or empty
                    sortByApi = 'name';
                    sortDirApi = 'ASC';
                }
                break;
        }

        // Choose correct API call: filter by brand if selected, else standard paged fetch
        let productsObservable;
        if (this.searchTerm) {
            productsObservable = this.productService.searchProducts(this.searchTerm, this.currentPage, this.pageSize, sortDirApi, sortByApi, this.selectedBrand); // Pass selectedBrand
        } else if (this.selectedBrand) {
            productsObservable = this.productService.filterByBrandName(this.selectedBrand, this.currentPage, this.pageSize, sortDirApi, sortByApi);
        } else {
            productsObservable = this.productService.getProductsPage(this.currentPage, this.pageSize, sortDirApi, sortByApi);
        }

        productsObservable.subscribe({
            next: (resp: any) => { // Add type any to resp
                this.products = resp.content;
                this.filteredProducts = resp.content;
                this.totalPages = resp.totalPages;
                this.totalItems = resp.totalItems;
                this.isFirstPage = resp.isFirst;
                this.isLastPage = resp.isLast;
                this.loading = false;
            },
            error: (err: any) => { // Add type any to err
                this.error = err.message || 'Failed to load products';
                this.loading = false;
            },
            complete: () => {
                this.updateUrl(); // Update URL after loading products
            }
        });
    }

    /**
     * Load all brands from API
     */
    loadBrands(): void {
        this.productService.getAllBrands().subscribe({
            next: (brands) => {
                // this.brands = [...new Set(brands)]; // Remove this line
            },
            error: (err) => {
                console.error('Error loading brands:', err);
            }
        });
    }

    /**
     * Load paginated brands from API
     */
    loadPaginatedBrands(): void {
        this.productService.getPaginatedBrands(this.brandPage, this.brandPageSize).subscribe({
            next: (resp: any) => { 
                console.log('Received paginated brands response:', resp);
                this.paginatedBrands = resp.content; 
                this.isFirstBrandPage = resp.isFirst;
                this.isLastBrandPage = resp.isLast;
                this.totalBrandPages = resp.totalPages;
                // Ensure brandPage is not out of bounds if totalPages changed
                if (this.brandPage >= this.totalBrandPages && this.totalBrandPages > 0) {
                    this.brandPage = this.totalBrandPages - 1;
                } else if (this.totalBrandPages === 0) {
                    this.brandPage = 0; // Reset to first page if no pages
                }
            },
            error: (err) => {
                console.error('Error loading paginated brands:', err);
                this.error = "Could not load brands. Please try again later.";
                this.paginatedBrands = [];
                this.totalBrandPages = 0;
                this.isFirstBrandPage = true;
                this.isLastBrandPage = true;
            }
        });
    }

    /**
     * Navigate to previous brand page
     */
    prevBrandPage(): void {
        if (this.brandPage > 0) {
            this.brandPage--;
            this.loadPaginatedBrands();
        }
    }

    /**
     * Navigate to next brand page
     */
    nextBrandPage(): void {
        if (!this.isLastBrandPage) {
            this.brandPage++;
            this.loadPaginatedBrands();
        }
    }

    filterByBrand(brandName: string): void {
        this.selectedBrand = brandName || null;
        this.searchTerm = null; // Clear any active search term
        this.currentPage = 0; 
        this.loadProducts(); // This will also call updateUrl
    }

    sortProducts(option: string): void {
        this.sortOption = option;
        this.currentPage = 0; 
        this.loadProducts(); // This will also call updateUrl
    }

    onPreviousPage(): void {
        if (!this.isFirstPage) {
            this.currentPage--;
            this.loadProducts();
        }
    }

    onNextPage(): void {
        if (!this.isLastPage) {
            this.currentPage++;
            this.loadProducts();
        }
    }

    hasPreviousPage(): boolean {
        return !this.isFirstPage;
    }

    hasNextPage(): boolean {
        return !this.isLastPage;
    }

    updateUrl(): void {
        const queryParams: any = {
            page: this.currentPage === 0 ? null : this.currentPage, // Remove page if it's default (0)
            sort: this.sortOption === 'name' ? null : this.sortOption, // Remove sort if it's default ('name')
            brand: this.selectedBrand || null, // Ensures brand is removed if null
            search: this.searchTerm || null    // Ensures search is removed if null
        };

        // Clean up null values from queryParams to avoid `key=null` in URL
        Object.keys(queryParams).forEach(key => {
            if (queryParams[key] === null || queryParams[key] === undefined) {
                delete queryParams[key];
            }
        });

        this.router.navigate([], {
            relativeTo: this.route,
            queryParams: queryParams,
            queryParamsHandling: 'merge', 
            replaceUrl: true
        });
    }

    addToCart(product: Product): void {
        this.cartService.addToCart(product);
        // Optionally, add a notification or visual feedback here
    }

    buyNow(product: Product): void {
        this.cartService.addToCart(product); // Add to cart first
        this.router.navigate(['/checkout']);
    }

    /**
     * Animate product image flying to cart icon and add to cart
     */
    animateAddToCart(event: MouseEvent, product: Product): void {
        // Add to cart immediately
        this.cartService.addToCart(product);
        // Find product card and image element
        const btn = event.currentTarget as HTMLElement;
        const card = btn.closest('.product-card') as HTMLElement;
        if (!card) return;
        const imageDiv = card.querySelector('.product-image') as HTMLElement;
        if (!imageDiv) return;
        // Extract image URL from background-image style
        const bg = imageDiv.style.backgroundImage || '';
        const urlMatch = bg.match(/url\("?(.*?)"?\)/);
        const imgUrl = urlMatch && urlMatch[1] ? urlMatch[1] : '';
        // Create flying image
        const flyer = document.createElement('img');
        flyer.src = imgUrl;
        const rect = imageDiv.getBoundingClientRect();
        flyer.style.position = 'fixed';
        flyer.style.left = rect.left + 'px';
        flyer.style.top = rect.top + 'px';
        flyer.style.width = rect.width + 'px';
        flyer.style.height = rect.height + 'px';
        flyer.style.transition = 'transform 0.8s ease-in-out, opacity 0.8s ease-in-out';
        flyer.style.zIndex = '1000';
        document.body.appendChild(flyer);
        // Calculate destination (cart icon)
        const cartIcon = document.getElementById('cart-icon');
        if (cartIcon) {
            const cartRect = cartIcon.getBoundingClientRect();
            const dx = (cartRect.left + cartRect.width/2) - (rect.left + rect.width/2);
            const dy = (cartRect.top + cartRect.height/2) - (rect.top + rect.height/2);
            requestAnimationFrame(() => {
                flyer.style.transform = `translate(${dx}px, ${dy}px) scale(0.2)`;
                flyer.style.opacity = '0.5';
            });
        }
        // Cleanup after animation
        flyer.addEventListener('transitionend', () => {
            flyer.remove();
        });
    }
}
<div class="flex flex-1 justify-center py-8">
    <div class="flex flex-col flex-1 gap-8">
        <div class="flex flex-wrap justify-between items-center gap-4 px-4 mb-6">
            <div class="flex flex-col gap-2">
                <h1 class="text-[#1b120e] tracking-tight text-4xl font-bold leading-tight">All Products</h1>
                <p class="text-[#7f5e53] text-base font-normal leading-relaxed">Explore our entire collection of
                    backpacks, designed for every adventure and lifestyle.</p>
            </div>
        </div>
        <div class="flex justify-between items-center gap-4 px-4 py-3 mb-6 rounded-xl bg-white shadow-sm">
            <div class="flex gap-2 items-center">
                <button aria-label="Sort Products"
                        class="p-2 text-[#7f5e53] hover:text-[#1b120e] hover:bg-[#fef5f0] rounded-md transition-colors">
                    <div data-icon="SortAscending" data-size="24px" data-weight="regular">
                        <svg fill="currentColor" height="24px" viewBox="0 0 256 256" width="24px"
                             xmlns="http://www.w3.org/2000/svg">
                            <path d="M128,128a8,8,0,0,1-8,8H48a8,8,0,0,1,0-16h72A8,8,0,0,1,128,128ZM48,72H184a8,8,0,0,0,0-16H48a8,8,0,0,0,0,16Zm56,112H48a8,8,0,0,0,0,16h56a8,8,0,0,0,0-16Zm125.66-21.66a8,8,0,0,0-11.32,0L192,188.69V112a8,8,0,0,0-16,0v76.69l-26.34-26.35a8,8,0,0,0-11.32,11.32l40,40a8,8,0,0,0,11.32,0l40-40A8,8,0,0,0,229.66,162.34Z"></path>
                        </svg>
                    </div>
                </button>
                <span class="text-sm text-[#7f5e53]">Sort by</span> <select
                    (change)="sortProducts($any($event.target).value)"
                    class="form-select text-sm text-[#1b120e] font-medium border-[#eb6c28] rounded-md focus:ring-2 focus:ring-[#eb6c28] focus:border-transparent">
                <option value="popularity">Popularity</option>
                <option value="price-low-high">Price: Low to High</option>
                <option value="price-high-low">Price: High to Low</option>
                <option value="newest">Newest</option>
            </select>
            </div>
            <div class="flex items-center gap-2">
                <span class="text-sm text-[#7f5e53]">Filter by Brand:</span>
                <select (change)="filterByBrand($any($event.target).value)"
                        class="form-select text-sm text-[#1b120e] font-medium border-[#eb6c28] rounded-md focus:ring-2 focus:ring-[#eb6c28] focus:border-transparent">
                    <option value="">All Brands</option>
                    <option *ngFor="let brand of paginatedBrands" [value]="brand"
                            [selected]="selectedBrand === brand">{{ brand }}
                    </option>
                </select>
            </div>
        </div>

        <!-- Loading indicator -->
        <div *ngIf="loading" class="flex justify-center py-8">
            <div class="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[#eb6c28]"></div>
        </div>
        <!-- Error message -->
        <div *ngIf="error" class="text-red-500 text-center py-4">
            {{ error }}
        </div>

        <!-- Empty state -->
        <div *ngIf="!loading && !error && filteredProducts.length === 0"
             class="flex flex-col items-center justify-center py-12">
            <div class="bg-gray-100 rounded-full p-6 mb-4">
                <svg xmlns="http://www.w3.org/2000/svg" class="h-12 w-12 text-gray-400" fill="none" viewBox="0 0 24 24"
                     stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                          d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/>
                </svg>
            </div>
            <h3 class="text-xl font-semibold text-gray-700 mb-2">No Products Found</h3>
            <p class="text-gray-500 text-center mb-6 max-w-md">We couldn't find any products matching your criteria.
                Please try a different filter or check back later.</p>
            <button (click)="filterByBrand('')"
                    class="px-4 py-2 bg-[#eb6c28] text-white rounded-lg hover:bg-[#d95f21] transition-colors">
                View All Products
            </button>
        </div>
        <div class="grid grid-cols-[repeat(auto-fit,minmax(220px,1fr))] gap-6 p-4">
            <!-- API products -->
            <div *ngFor="let product of filteredProducts"
                 class="product-card flex flex-col h-full gap-4 pb-4 rounded-xl overflow-hidden shadow-sm hover:shadow-lg transition-shadow duration-300 bg-white">
                <a class="block overflow-hidden" [routerLink]="['/product-detail', product.id]">
                    <div class="product-image w-full bg-center bg-no-repeat aspect-[4/3] bg-cover"
                         [style.background-image]="'url(' + product.imageLink + ')'">
                    </div>
                </a>
                <div class="px-4 flex flex-col flex-grow">
                    <a class="block text-[#1b120e] text-lg font-semibold leading-normal hover:text-[#eb6c28] transition-colors"
                       [routerLink]="['/product-detail', product.id]">{{ product.name }}</a>
                    <p class="text-[#7f5e53] text-sm font-normal leading-normal mt-1 flex-grow">{{ product.brandName }}</p>
                    <p class="text-[#eb6c28] text-base font-bold leading-normal mt-2">{{ product.price }}</p>
                </div>
                <div class="px-4 mt-auto flex flex-col sm:flex-row gap-2">
                    <button (click)="animateAddToCart($event, product)"
                            class="flex-1 whitespace-nowrap text-sm font-medium leading-normal text-[#1b120e] bg-transparent border border-[#eb6c28] hover:bg-[#fef5f0] rounded-md px-3 py-2 transition-colors">
                        Add to Cart
                    </button>
                    <button (click)="buyNow(product)"
                            class="flex-1 whitespace-nowrap text-sm font-medium leading-normal text-white bg-[#eb6c28] hover:bg-[#d95f21] rounded-md px-3 py-2 transition-colors">
                        Buy Now
                    </button>
                </div>
            </div>
        </div> <!-- grid container -->

        <!-- Pagination Buttons -->
        <div class="flex justify-center items-center gap-4 py-4">
            <button 
                class="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50"
                (click)="onPreviousPage()" 
                [disabled]="!hasPreviousPage()">
                Previous
            </button>
            <button 
                class="px-4 py-2 bg-[#eb6c28] text-white rounded-lg hover:bg-[#d95f21] transition-colors disabled:opacity-50"
                (click)="onNextPage()"
                [disabled]="!hasNextPage()">
                Next
            </button>
        </div>

    </div>
</div>
